harness.enable:
const results = await axe.run({
  runOnly: { type: 'rule', values: Object.keys(m.axeHandlers) }
});
for (const violation of results.violations) {
  const handler = m.axeHandlers[violation.id];
  if (!handler) continue;
  for (const node of violation.nodes) {
    try {
      const el = document.querySelector(node.target[0]);
      if (!el) continue;
      const check = node.any?.find(c => c.id === violation.id) || node.all?.find(c => c.id === violation.id);
      const fg = check?.data?.fgColor;
      const bg = check?.data?.bgColor;
      await handler(el, fg, bg);
    } catch (e) {
      console.error('Handler error:', e);
    }
  }
}
